import{_ as r,C as t,o as e,c as d,j as i,a as n,E as s,a2 as o}from"./chunks/framework.C21TwvGF.js";const O=JSON.parse(`{"title":"2-dars (Mentor). Operatsion tizimlar va Windows muhitida ishlash","description":"","frontmatter":{"title":"2-dars (Mentor). Operatsion tizimlar va Windows muhitida ishlash","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":1,"link":"/mentor/8-sinf-cs/hafta-01/"},"g":2,"title":"Operatsion tizimlar va Windows muhitida ishlash","lead":"Kompyuterni yoqqaningizda ekranda jilvalanadigan chiroyli ish stoli va derazalar ortida qanday kuch turibdi? Ushbu darsda kompyuterning «boshqaruvchi yuragi» bo'lgan operatsion tizimlar, Windows 10/11 imkoniyatlari, oynalarni bo'lish va dasturlarni professional boshqarishni o'rganamiz.","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-2-test.html","student_link":"/8-sinf-cs/hafta-01/dars-2","tabs":[{"g":1,"link":"/mentor/8-sinf-cs/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/8-sinf-cs/hafta-01/dars-2","current":true},{"g":3,"link":"/mentor/8-sinf-cs/hafta-01/dars-3","current":false}],"prev":{"g":1,"title":"Zamonaviy kompyuterlar va ularning arxitekturasi","link":"/mentor/8-sinf-cs/hafta-01/dars-1"},"next":{"g":3,"title":"Axborot o‘lchov birliklari va fayl turlari. Windows operatsion tizimida fayl hamda papkalar yaratish. Tezkor tugmalar (Hot keys)","link":"/mentor/8-sinf-cs/hafta-01/dars-3"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-01/dars-2.md","filePath":"mentor/8-sinf-cs/hafta-01/dars-2.md"}`),h={name:"mentor/8-sinf-cs/hafta-01/dars-2.md"},u={class:"blk"},m={id:"_1-dars-rejasi",tabindex:"-1"},g={class:"blk"},p={id:"_2-dars-konspekti",tabindex:"-1"},y={class:"blk"},k={id:"_3-kod-amaliy-buyruqlar",tabindex:"-1"},b={class:"blk"},c={id:"_4-amaliy-topshiriqlar",tabindex:"-1"},q={class:"blk"},v={id:"_5-tezkor-nazorat",tabindex:"-1"},z={class:"blk"},f={id:"_6-uyga-vazifa",tabindex:"-1"};function _(x,a,S,T,W,A){const l=t("Icon");return e(),d("div",null,[a[18]||(a[18]=i("p",null,[i("strong",null,"Hafta:"),n(" 1 · "),i("strong",null,"Davomiyligi:"),n(" 80 daqiqa · "),i("strong",null,"Turi:"),n(" nazariya + amaliyot · "),i("strong",null,"I-bob"),n(", 2-dars")],-1)),i("div",u,[i("h2",m,[s(l,{name:"file-text"}),a[0]||(a[0]=n(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o('<p><strong>Maqsad:</strong> o&#39;quvchilarga operatsion tizim (OT) tushunchasi, uning asosiy vazifalari, shaxsiy kompyuter va mobil qurilmalar uchun zamonaviy OT turlari (Windows, Linux, macOS, Android, iOS), Windows 10/11 ish stoli muhiti, Start menyusi, vazifalar paneli, oynalarni boshqarish (Snap layouts), tizim sozlamalari hamda dasturlarni o&#39;rnatish va o&#39;chirish ko&#39;nikmalarini amaliy o&#39;rgatish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Operatsion tizim nima ekanligini va nima uchun kompyuterga OT zarurligini tushuntirib bera oladi.</li><li>Windows, Linux va macOS operatsion tizimlarining o&#39;ziga xos xususiyatlarini farqlaydi.</li><li>Windows ish stoli, Start menyusi va oynalar bilan tezkor ishlay oladi (Snap layouts, <code>Win + strelkalar</code>).</li><li>Windows Sozlamalari (Settings) va Boshqaruv paneli (Control Panel) orqali kompyuterni moslay oladi.</li><li>Dasturlarni to&#39;g&#39;ri o&#39;rnatish (.exe / .msi) va xavfsiz to&#39;liq o&#39;chirish (Uninstall) amallarini bajara oladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>1-darsni takrorlash (CPU, RAM, arxitektura). «Kompyuter qismlari bor, ammo ekranda nima ko&#39;rinadi?» muammoli savoli</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Operatsion tizim tushunchasi, apparat va dasturiy vositachi roli, Windows, Linux, macOS, Android, iOS</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Jismoniy harakat mashqlari</td></tr><tr><td>35–65 daq</td><td>Amaliyot</td><td>Windows oynalarini boshqarish, Start menyusi, Snap layouts, Settings vs Control Panel, dasturlar ro&#39;yxatini ko&#39;rish</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol va amaliy vazifa</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Asosiy xulosalarni jamlash va uyga topshiriq</td></tr></tbody></table><hr>',5))]),i("div",g,[i("h2",p,[s(l,{name:"file-text"}),a[3]||(a[3]=n(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=o('<h3 id="_2-1-operatsion-tizim-nima-va-u-nega-kerak" tabindex="-1">2.1. Operatsion tizim nima va u nega kerak? <a class="header-anchor" href="#_2-1-operatsion-tizim-nima-va-u-nega-kerak" aria-label="Permalink to &quot;2.1. Operatsion tizim nima va u nega kerak?&quot;">​</a></h3><p><strong>Operatsion tizim (OT / Operating System — OS)</strong> — bu kompyuterning barcha texnik apparat qismlarini (CPU, RAM, disklar, monitor, klaviatura) boshqaradigan va foydalanuvchi hamda dasturlarning kompyuter bilan qulay muloqotini ta&#39;minlaydigan asosiy tizimli dasturlar majmuasi.</p><p>Agar operatsion tizim bo&#39;lmaganida:</p><ul><li>Kompyuter shunchaki temir va mikrosxemalar to&#39;plami bo&#39;lib qolardi.</li><li>Har bir dasturchi o&#39;z dasturini yozayotganda ekranning har bir pikseliga rang berish, klaviaturaning har bir tugmasidan signalni qabul qilish kabi millionlab mayda texnik buyruqlarni noldan yozishi kerak bo&#39;lardi.</li><li>Operatsion tizim barcha texnik murakkabliklarni o&#39;z zimmasiga oladi va foydalanuvchiga qulay <strong>Grafik foydalanuvchi interfeysi (GUI — Graphical User Interface)</strong> taqdim etadi.</li></ul><h3 id="_2-2-zamonaviy-operatsion-tizimlar-turlari" tabindex="-1">2.2. Zamonaviy operatsion tizimlar turlari <a class="header-anchor" href="#_2-2-zamonaviy-operatsion-tizimlar-turlari" aria-label="Permalink to &quot;2.2. Zamonaviy operatsion tizimlar turlari&quot;">​</a></h3><ol><li><strong>Shaxsiy kompyuterlar (PC) uchun:</strong><ul><li><strong>Microsoft Windows (Windows 10, 11):</strong> Dunyodagi eng mashhur shaxsiy kompyuter OT (bozordagi ulushi ~70%). Foydalanish sodda, o&#39;yinlar va ofis dasturlarining deyarli barchasi unga moslashgan.</li><li><strong>macOS:</strong> Apple kompaniyasining Mac kompyuterlari uchun maxsus ishlab chiqilgan OT. Yuqori darajadagi xavfsizlik, chiroyli dizayn va tezkorlikka ega.</li><li><strong>Linux (Ubuntu, Debian, Fedora, Arch):</strong> Ochiq kodli (Open-source), bepul va o&#39;ta xavfsiz OT. Dunyodagi aksariyat serverlar, bulut tizimlari, superkompyuterlar va dasturchilar aynan Linux asosida ishlaydi.</li></ul></li><li><strong>Mobil qurilmalar uchun:</strong><ul><li><strong>Android:</strong> Google kompaniyasi tomonidan Linux yadrosi asosida yaratilgan, ochiq kodli eng ommabop mobil OT.</li><li><strong>iOS:</strong> Apple kompaniyasining iPhone va iPad qurilmalari uchun yaratilgan yopiq va xavfsiz mobil tizim.</li></ul></li></ol><h3 id="_2-3-windows-ish-stoli-muhiti-elementlari" tabindex="-1">2.3. Windows ish stoli muhiti elementlari <a class="header-anchor" href="#_2-3-windows-ish-stoli-muhiti-elementlari" aria-label="Permalink to &quot;2.3. Windows ish stoli muhiti elementlari&quot;">​</a></h3><ul><li><strong>Ish stoli (Desktop):</strong> Tizim yuklangandan so&#39;ng ekranda paydo bo&#39;ladigan asosiy ish maydoni. Unda fayllar, papkalar va yorliqlar (Shortcuts) joylashadi.</li><li><strong>Vazifalar paneli (Taskbar):</strong> Odatda ekranning pastki qismida joylashgan chiziq. Unda Start tugmasi, qidiruv paneli, mahkamlangan va hozirda ochiq bo&#39;lgan dasturlar belgilari turadi.</li><li><strong>Start (Boshlash) menyusi:</strong> Kompyuterga o&#39;rnatilgan barcha dasturlar, tizim sozlamalari va kompyuterni o&#39;chirish/qayta yuklash (Power) tugmalarini jamlagan bosh menyu.</li><li><strong>Bildirishnomalar maydoni (System Tray):</strong> Vazifalar panelining o&#39;ng quyi burchagida joylashgan soat, sana, til indikatori, internet (Wi-Fi), tovush balandligi va batareya holati ko&#39;rinib turadigan maydon.</li></ul><h3 id="_2-4-oynalar-bilan-professional-ishlash-snap-layouts" tabindex="-1">2.4. Oynalar bilan professional ishlash (Snap layouts) <a class="header-anchor" href="#_2-4-oynalar-bilan-professional-ishlash-snap-layouts" aria-label="Permalink to &quot;2.4. Oynalar bilan professional ishlash (Snap layouts)&quot;">​</a></h3><p>Windows nomi inglizcha «Windows» (oynalar) so&#39;zidan olingan bo&#39;lib, har bir dastur to&#39;rtburchak oynada ochiladi.</p><ul><li>Oynaning yuqori o&#39;ng burchagidagi 3 ta boshqaruv tugmasi: <ul><li><code>-</code> (Minimize) — oynani vazifalar paneliga yashirish;</li><li><code>□</code> (Maximize / Restore) — oynani butun ekranga yoyish yoki oldingi o&#39;lchamiga qaytarish;</li><li><code>X</code> (Close) — dasturni butunlay yopish (<code>Alt + F4</code>).</li></ul></li><li><strong>Snap layouts (Ekran maydonini bo&#39;lish):</strong><ul><li><code>Win + Chapga strelka</code> — oynani ekranning chap yarmiga joylashtirish.</li><li><code>Win + O&#39;ngga strelka</code> — oynani o&#39;ng yarmiga joylashtirish.</li><li>Bu dasturchiga bir vaqtning o&#39;zida bir tomonda kod yozib, ikkinchi tomonda natijani ko&#39;rish imkonini beradi.</li></ul></li></ul><h3 id="_2-5-tizim-sozlamalari-va-boshqaruv-paneli" tabindex="-1">2.5. Tizim sozlamalari va Boshqaruv paneli <a class="header-anchor" href="#_2-5-tizim-sozlamalari-va-boshqaruv-paneli" aria-label="Permalink to &quot;2.5. Tizim sozlamalari va Boshqaruv paneli&quot;">​</a></h3><ul><li><strong>Sozlamalar (Settings, <code>Win + I</code>):</strong> Zamonaviy va qulay Windows sozlamalar markazi. Unda ekran yorqinligi, internet, shaxsiylashtirish (fon rasmi, mavzu) va o&#39;rnatilgan ilovalar boshqariladi.</li><li><strong>Boshqaruv paneli (Control Panel):</strong> Chuqurroq tizim sozlamalari, drayverlar va ma&#39;muriy vositalar joylashgan an&#39;anaviy panel.</li></ul><h3 id="_2-6-dasturlarni-o-rnatish-va-to-g-ri-o-chirish" tabindex="-1">2.6. Dasturlarni o&#39;rnatish va to&#39;g&#39;ri o&#39;chirish <a class="header-anchor" href="#_2-6-dasturlarni-o-rnatish-va-to-g-ri-o-chirish" aria-label="Permalink to &quot;2.6. Dasturlarni o&#39;rnatish va to&#39;g&#39;ri o&#39;chirish&quot;">​</a></h3><ul><li><strong>Dastur o&#39;rnatish:</strong> Internetdan yuklab olingan o&#39;rnatuvchi fayllar (<code>.exe</code> yoki <code>.msi</code> kengaytmali) administrator huquqi bilan ishga tushiriladi va o&#39;rnatish ustasi (Setup Wizard) qadamlari bo&#39;yicha o&#39;rnatiladi.</li><li><strong>Dasturni o&#39;chirish:</strong> Shunchaki ish stolidagi yorliqni (Shortcut) «Delete» bilan o&#39;chirish dasturni kompyuterdan o&#39;chirmaydi! Dasturni to&#39;liq o&#39;chirish uchun: <ul><li><code>Win + I</code> → «Apps» (Ilovalar) → «Installed apps» (O&#39;rnatilgan ilovalar) bo&#39;limiga kiriladi va kerakli dastur ro&#39;yxatdan topilib, «Uninstall» tugmasi bosiladi.</li></ul></li></ul><hr>',16))]),i("div",y,[i("h2",k,[s(l,{name:"file-text"}),a[6]||(a[6]=n(" 3. Kod / Amaliy buyruqlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-kod-amaliy-buyruqlar","aria-label":'Permalink to "<Icon name="file-text" /> 3. Kod / Amaliy buyruqlar"'},"​",-1))]),a[8]||(a[8]=o(`<p>Windows muhitida tezkor boshqaruv buyruqlari:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 1. Sozlamalar oynasini ochish</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Win + I</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 2. Ishlayotgan dasturlar o&#39;rtasida tezkor almashish</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Alt + Tab</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 3. Barcha ochiq oynalarni bir zumda minimallashtirib ish stolini ko&#39;rsatish</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Win + D</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 4. Fayl boshqaruvchisini (File Explorer) ochish</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Win + E</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 5. Oynani yopish</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Alt + F4</span></span></code></pre></div><hr>`,3))]),i("div",b,[i("h2",c,[s(l,{name:"file-text"}),a[9]||(a[9]=n(" 4. Amaliy topshiriqlar ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Amaliy topshiriqlar"'},"​",-1))]),a[11]||(a[11]=o('<h3 id="_1-topshiriq-oson" tabindex="-1">1-topshiriq (oson) <a class="header-anchor" href="#_1-topshiriq-oson" aria-label="Permalink to &quot;1-topshiriq (oson)&quot;">​</a></h3><p>Klaviaturadagi <code>Win + I</code> kombinatsiyasi orqali Windows Sozlamalarini (Settings) oching. «System» bo&#39;limidagi «About» (Tizim haqida) bandiga o&#39;tib, Windows operatsion tizimingizning versiyasini (masalan, Windows 10 yoki Windows 11) va nashrini (Pro, Home) aniqlang.</p><p><strong>Kutiladigan natija:</strong> Operatsion tizimning to&#39;liq nomi va versiyasi yoziladi.</p><p><strong>Yechim:</strong></p><ol><li><code>Win + I</code> bosiladi.</li><li>Chap menyudan «System» tanlanadi va eng pastdagi «About» tugmasi bosiladi.</li><li>«Windows specifications» bo&#39;limida Edition (masalan: <em>Windows 11 Pro</em>) va Version (masalan: <em>23H2</em>) ko&#39;rinadi.</li></ol><hr><h3 id="_2-topshiriq-o-rta" tabindex="-1">2-topshiriq (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-o-rta" aria-label="Permalink to &quot;2-topshiriq (o&#39;rta)&quot;">​</a></h3><p>Brauzer (masalan, Google Chrome) va Bloknot (Notepad) dasturlarini oching. Snap mexanizmidan foydalanib, ekranning chap yarmiga brauzerni, o&#39;ng yarmiga esa bloknotni aniq 50/50 qilib joylashtiring.</p><p><strong>Kutiladigan natija:</strong> Ekran teng ikkiga bo&#39;lingan holda ikkala dastur yonma-yon ishlaydi.</p><p><strong>Yechim:</strong></p><ol><li>Brauzer oynasini tanlab, <code>Win + Chapga strelka</code> bosiladi.</li><li>Bloknot oynasini tanlab, <code>Win + O&#39;ngga strelka</code> bosiladi.</li><li>Ikkala oyna ekranni to&#39;ldirib, bir-birini to&#39;smagan holda joylashadi.</li></ol><hr><h3 id="_3-topshiriq-qiyin" tabindex="-1">3-topshiriq (qiyin) <a class="header-anchor" href="#_3-topshiriq-qiyin" aria-label="Permalink to &quot;3-topshiriq (qiyin)&quot;">​</a></h3><p>Kompyuteringizda o&#39;rnatilgan ilovalar ro&#39;yxatini oching (<code>Win + I</code> → Apps → Installed apps). Ro&#39;yxatdan kompyuteringizda o&#39;rnatilgan 5 ta dasturni, ularning egallagan disk hajmini (MB yoki GB) aniqlang va keraksiz bitta yordamchi ilovani to&#39;g&#39;ri «Uninstall» qilish tartibini ko&#39;rsating.</p><p><strong>Kutiladigan natija:</strong> 5 ta dastur nomi, ularning hajmi jadvali tuziladi; dasturni o&#39;chirishning to&#39;liq ketma-ketligi yoziladi.</p><p><strong>Yechim:</strong></p><ol><li><code>Win + I</code> orqali «Apps» → «Installed apps» (yoki «Apps &amp; features») bo&#39;limiga kiriladi.</li><li>Dasturlar ro&#39;yxatidan 5 ta dastur (masalan, Google Chrome, VS Code, VLC Player, Telegram, Flowgorithm) va ularning hajmi yozib olinadi.</li><li>Keraksiz ilovani o&#39;chirish uchun uning yonidagi 3 nuqta <code>...</code> belgisi bosilib, «Uninstall» buyrug&#39;i tanlanadi va tasdiqlanadi.</li></ol><hr>',18))]),i("div",q,[i("h2",v,[s(l,{name:"file-text"}),a[12]||(a[12]=n(" 5. Tezkor nazorat ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-nazorat","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor nazorat"'},"​",-1))]),a[14]||(a[14]=o("<ol><li>Operatsion tizimning kompyuterdagi asosiy vazifasi nima? <ul><li><em>Javob:</em> Apparat qismlarini boshqarish, dasturlar ishlashini ta&#39;minlash va foydalanuvchiga qulay grafik interfeys berish.</li></ul></li><li>PC uchun eng mashhur 3 ta operatsion tizimni ayting. <ul><li><em>Javob:</em> Windows, Linux, macOS.</li></ul></li><li>Ish stolidagi dastur yorlig&#39;ini (Shortcut) Delete bilan o&#39;chirish dasturni kompyuterdan to&#39;liq o&#39;chiradimi? <ul><li><em>Javob:</em> Yo&#39;q! Bu faqat uning belgisini o&#39;chiradi. Dastur fayllari diskda qoladi. To&#39;liq o&#39;chirish uchun «Uninstall» qilish kerak.</li></ul></li><li>Ekranni ikkita oyna o&#39;rtasida teng ikkiga bo&#39;lish uchun qaysi klavishlar kombinatsiyasi bosiladi? <ul><li><em>Javob:</em> <code>Win + Chapga strelka</code> va <code>Win + O&#39;ngga strelka</code>.</li></ul></li><li>Barcha ochiq oynalarni bir zumda yashirib, ish stoliga o&#39;tish tugmasi qaysi? <ul><li><em>Javob:</em> <code>Win + D</code>.</li></ul></li></ol><hr>",2))]),i("div",z,[i("h2",f,[s(l,{name:"file-text"}),a[15]||(a[15]=n(" 6. Uyga vazifa ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 6. Uyga vazifa"'},"​",-1))]),a[17]||(a[17]=i("ol",null,[i("li",null,[n("O'z kompyuteringizda quyidagi 4 ta tezkor buyruqni amalda sinab ko'ring va ularning har biri nima qilishini daftaringizga yozing: "),i("ul",null,[i("li",null,[i("code",null,"Win + E")]),i("li",null,[i("code",null,"Win + D")]),i("li",null,[i("code",null,"Win + I")]),i("li",null,[i("code",null,"Alt + Tab")])])]),i("li",null,"Kompyuteringizda o'rnatilgan 3 ta eng katta hajmli dasturning nomi va hajmini Settings orqali aniqlab yozing. Vazifani bajarish vaqti: 20 daqiqa.")],-1))])])}const P=r(h,[["render",_]]);export{O as __pageData,P as default};
